// Site metadata (shared by build-time RSS / sitemap / OG / llms.txt and runtime external
// links). Note: UI-layer copy (brand name / author name / hero copy) does not live here —
// it lives in the lib/i18n/*.ts wordbooks and switches with the UI language; this file
// only carries metadata that is never translated.

/** giscus comment config (repository and category identifiers required by the
 *  github.com/giscus/giscus component) */
interface GiscusConfig {
  /** Repository identifier in owner/repo form */
  repo: `${string}/${string}`;
  /** Repository's GraphQL node id (generated by giscus.app) */
  repoId: string;
  /** Discussion category name */
  category: string;
  /** Category's GraphQL node id (generated by giscus.app); an empty string means unconfigured */
  categoryId: string;
}

export const siteConfig = {
  // Baseline SEO title and description (build-time metadata; language follows the content: Chinese)
  title: "ZJBlog",
  description: "Zhijie He's personal technical blog and project showcase",
  // Canonical site URL (used by RSS / sitemap / OpenGraph)
  url: "https://www.zhijie.online",
  // Author's Chinese name (used in build-time copy like llms.txt; UI display uses i18n's site.author)
  author: "Zhijie He",
  // Footer copyright holder (© {year} <copyright>; personal wordmark — does not change with the product name and is not translated with the UI language)
  copyright: "Zhijie Online",
  social: {
    github: "https://github.com/hezhijie0327",
  },
  // giscus comments (powered by GitHub Discussions, mapped per page path). repo / repoId
  // come from repository metadata; category / categoryId come from the giscus.app-generated
  // config.
  giscus: {
    repo: "hezhijie0327/ZJBlog",
    repoId: "R_kgDOQsmIRg",
    category: "Announcements",
    categoryId: "DIC_kwDOQsmIRs4C0EgF",
  } satisfies GiscusConfig,
};

// How many "featured projects" the home page shows; the remaining personal projects collapse into "more projects"
export const featuredProjectCount = 4;
// Display cap of the "more projects" list (the rest are reached via "view all projects")
export const moreProjectsCount = 4;
